-- Better Lobby Management port, L11 (read-only): dumps the game.dll code that is encrypted in every capture of
-- build 26088801 (kick_peer, the chat message sender, the lobby search builder) once the game has run it, and
-- the protection of every game.dll code page the mod reads or calls. Generated by tools/make_probes.py.
-- Best after: a lobby search (Galactic Map scanner or quickplay), a chat line, and a kick by the host.
local G = assert(game)
local function hex(s) return (s:gsub('.', function(c) return fmt('%02x', c:byte()) end)) end
local DUMPS = {
  {'kick_peer', 0xf1d8f0, 0x40},
  {'chat message RPC', 0xc09a40, 0xc0},
  {'search builder (continent filter, flag check)', 0x11cfed0, 0x900},
}
for _, d in ipairs(DUMPS) do
  local name, rva, size = d[1], d[2], d[3]
  local r = region(G + rva)
  out('BLM_L11 region', name, fmt('0x%X', rva), r and fmt('prot 0x%X base 0x%X size 0x%X', r.protection, r.base - G, r.size) or 'none')
  local got = 0
  for at = 0, size - 1, 128 do
    local n = math.min(128, size - at)
    local s = read(G + rva + at, n)
    if s then out('BLM_DUMP', fmt('0x%X', rva + at), hex(s)); got = got + n end
  end
  out('BLM_L11', name, got == size and 'dumped' or (got == 0 and 'not resident yet (unreadable)' or 'partly readable'), got, 'of', size)
end
local PAGES = {0x520000, 0x676000, 0x678000, 0x684000, 0xb7b000, 0xbfc000, 0xc09000, 0xc12000, 0xecf000, 0xf13000, 0xf17000, 0xf1a000, 0xf1d000, 0xf20000, 0xf22000, 0xf24000, 0xf25000, 0xf27000, 0xf28000, 0x117a000, 0x11cc000, 0x11cd000, 0x11d0000, 0x11d2000, 0x11d3000, 0x11e5000, 0x1287000, 0x128e000, 0x12d1000, 0x12d3000, 0x12d4000, 0x12d9000, 0x12e4000, 0x12e5000, 0x12e8000, 0x130c000, 0x1621000, 0x16e1000, 0x1778000, 0x177b000, 0x177c000, 0x177d000}
local by = {}
for _, p in ipairs(PAGES) do
  local r = region(G + p)
  local k = r and fmt('0x%X', r.protection) or 'none'
  by[k] = (by[k] or 0) + 1
  if not r or r.protection == 0x1 then out('BLM_L11 page not resident yet', fmt('0x%X', p)) end
end
local s = {} for k, v in pairs(by) do s[#s + 1] = k .. ': ' .. v end
out('BLM_L11 code pages the mod reads or calls by protection (0x20 executable+read, 0x1 no access):', table.concat(s, ', '))
return true
